function [tau] = mtq_tango(q, w, q_ref, w_ref, pth, pw)
%MTQ_TANGO  P3 TANGO (Chasset et al. 2013): LQR with P frozen at the averaged Riccati solution:
%   tau = -(P_th theta + P_w w_e), theta = 2 s q_v.
%   q: real[1][4] (passed a plain number)
%   w: real[1][3] (passed a plain number)
%   q_ref: real[1][4] (passed a plain number)
%   w_ref: real[1][3] (passed a plain number)
%   pth: real[1][3][3] (passed a plain number)
%   pw: real[1][3][3] (passed a plain number)
%   returns tau: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(3, 1);
    [qe, s, wr, we] = asils.alg.control.mtq_err(q, w, q_ref, w_ref);
    th = zeros(3, 1);
    i = ((0):((3) - 1)).';
    th((i) + 1) = ((2 * s) .* reshape(qe((i) + 1), [], 1));
    aa = [pth(1, 1)*th(1) + pth(1, 2)*th(2) + pth(1, 3)*th(3); pth(2, 1)*th(1) + pth(2, 2)*th(2) + pth(2, 3)*th(3); pth(3, 1)*th(1) + pth(3, 2)*th(2) + pth(3, 3)*th(3)];
    bb = [pw(1, 1)*we(1) + pw(1, 2)*we(2) + pw(1, 3)*we(3); pw(2, 1)*we(1) + pw(2, 2)*we(2) + pw(2, 3)*we(3); pw(3, 1)*we(1) + pw(3, 2)*we(2) + pw(3, 3)*we(3)];
    i = ((0):((3) - 1)).';
    tau((i) + 1) = (-((reshape(aa((i) + 1), [], 1) + reshape(bb((i) + 1), [], 1))));
end
